DIGITS = "0123456789ABCDEF"

def to_base(n, base):
    if n == 0:
        return "0"
    out = ""
    while n > 0:
        out = DIGITS[n % base] + out
        n //= base
    return out

def read_digits(text, base):
    """The value of text in base, or None if a character is not a digit of that base."""
    if text == "":
        return None
    value = 0
    for ch in text.upper():
        if ch not in DIGITS[:base]:
            return None
        value = value * base + DIGITS.index(ch)
    return value

def read_number(text):
    lower = text.lower()
    if lower.startswith("0x"):
        return read_digits(text[2:], 16)
    if lower.startswith("0b"):
        return read_digits(text[2:], 2)
    return read_digits(text, 10)

def signed_value(pattern):
    value = read_digits(pattern, 2)
    if pattern[0] == "1":
        value -= 2 ** len(pattern)
    return value

def run(words):
    command = words[0].lower()
    if command in ("bin", "hex", "dec"):
        if len(words) != 2:
            return f"Not a number: {' '.join(words[1:])}"
        value = read_digits(words[1], 10) if command != "dec" else read_number(words[1])
        if value is None:
            return f"Not a number: {words[1]}"
        if command == "bin":
            return f"{value} = 0b{to_base(value, 2)}"
        if command == "hex":
            return f"{value} = 0x{to_base(value, 16)}"
        return f"{words[1]} = {value}"
    if command == "signed":
        bits = read_digits(words[1], 10) if len(words) == 3 else None
        if bits is None:
            return f"Not a number: {' '.join(words[1:])}"
        pattern = words[2]
        if read_digits(pattern, 2) is None:
            return f"Not a number: {pattern}"
        if len(pattern) != bits:
            return f"The pattern must have exactly {bits} bits"
        return f"{pattern} as signed {bits}-bit = {signed_value(pattern)}"
    if command == "range":
        bits = read_digits(words[1], 10) if len(words) == 2 else None
        if not bits:
            return f"Not a number: {' '.join(words[1:])}"
        return f"{bits} bits: unsigned 0 to {2 ** bits - 1}, signed {-(2 ** (bits - 1))} to {2 ** (bits - 1) - 1}"
    return f"Unknown command: {words[0]}"

while True:
    try:
        line = input()
    except EOFError:
        break
    words = line.split()
    if not words:
        continue
    if words[0].lower() == "quit":
        break
    print(run(words))
